<script setup lang="ts">
import { computed } from 'vue';
import type { BilibiliSettings } from '../../../../packages/contracts/src/plugins/bilibili';
const model = defineModel<BilibiliSettings>({ required: true });
const props = defineProps<{ loginStatus?: string; qrUrl?: string; qrImage?: string; busy?: boolean }>();
const emit = defineEmits<{ login: []; poll: []; logout: [] }>();
const groups = computed({ get: () => model.value.groupIds.join('\n'), set: (value: string) => { model.value.groupIds = value.split(/[\s,，]+/).filter(Boolean); } });
</script>
<template><section class="media-settings"><p class="hint">本页参数在下方保存插件配置后生效；扫码登录和清除凭据立即独立生效。</p>
<label class="toggle"><input v-model="model.enabled" type="checkbox" />启用 Bilibili</label>
<p class="hint">提供搜索、视频内容、UP 主、直播、番剧、专栏、音频和评论工具。需在 Agent 中挂载对应工具，群黑白名单同时生效。</p>
<fieldset><legend>账号登录</legend><p>{{ props.loginStatus || '登录状态由服务器校验，Cookie 不会返回浏览器。' }}</p><div class="buttons"><button type="button" :disabled="busy" @click="emit('login')">获取登录二维码</button><button type="button" :disabled="busy || !qrUrl" @click="emit('poll')">检查扫码状态</button><button type="button" :disabled="busy" @click="emit('logout')">清除扫码凭据</button></div><img v-if="qrImage" :src="qrImage" alt="Bilibili 登录二维码" class="qr" /><a v-if="qrUrl" :href="qrUrl" target="_blank" rel="noopener noreferrer">打开本次登录链接</a><label>可选 Cookie 密钥引用<input v-model="model.cookieSecret" /></label><p class="hint">Cookie 在管理设置的密钥库中只写保存。扫码清除不会删除外部密钥。</p></fieldset>
<div class="grid"><label>群访问策略<select v-model="model.accessMode"><option value="blacklist">排除列表内群</option><option value="whitelist">仅列表内群</option></select></label><label>群号列表<textarea v-model="groups" rows="3" /></label><label>总结风格<select v-model="model.summaryStyle"><option value="concise">简洁</option><option value="detailed">详细</option><option value="professional">专业</option></select></label><label>总结最大字数<input v-model.number="model.maxSummaryChars" type="number" min="500" max="10000" /></label><label>总结缓存（小时）<input v-model.number="model.cacheHours" type="number" min="1" max="720" /></label><label class="toggle"><input v-model="model.outputImage" type="checkbox" />总结使用图片卡片（渲染失败回退文本）</label></div>
<label class="toggle"><input v-model="model.autoDetect" type="checkbox" />自动识别消息中的 B站链接</label><label class="toggle"><input v-model="model.autoSummary" type="checkbox" />识别后调用当前 Agent 模型生成总结</label>
<fieldset><legend>字幕与语音转写</legend><p class="hint">优先字幕。无字幕时才转写；Bcut 会将音频上传必剪服务。本地服务上传限制在所配置服务地址。转写需要 FFmpeg、视频访问权限和外部写入权限。</p><div class="grid"><label>ASR 提供方<select v-model="model.asr.provider"><option value="disabled">关闭（仅字幕）</option><option value="bcut">Bcut 必剪</option><option value="local_multimodal_infra">本地多模态服务</option></select></label><label>最长视频（秒）<input v-model.number="model.asr.maxDurationSeconds" type="number" min="60" max="14400" /></label><label>总超时（秒）<input v-model.number="model.asr.timeoutSeconds" type="number" min="30" max="1800" /></label><label>音轨最大字节数<input v-model.number="model.asr.maxAudioBytes" type="number" min="1000000" max="100000000" /></label></div><div v-if="model.asr.provider==='local_multimodal_infra'" class="grid"><label>服务地址<input v-model="model.asr.baseUrl" type="url" /></label><label>令牌密钥引用<input v-model="model.asr.tokenSecret" /></label><label>转写模型<input v-model="model.asr.model" /></label><label>时间轴粒度（秒）<input v-model.number="model.asr.granularitySeconds" type="number" min="1" max="120" /></label><label class="toggle"><input v-model="model.asr.speakerDiarization" type="checkbox" />标记说话人</label></div></fieldset>
<fieldset><legend>UP 主订阅</legend><label class="toggle"><input v-model="model.autoPush" type="checkbox" />启用已有订阅的定时更新</label><div class="grid"><label>检查间隔（分钟）<input v-model.number="model.pollMinutes" type="number" min="5" max="1440" /></label><label>每位发送者每会话订阅上限<input v-model.number="model.maxSubscriptions" type="number" min="1" max="100" /></label></div><p class="hint">使用 /订阅、/取消订阅、/订阅列表、/检查更新；不会自动创建订阅。更新仅发送到原会话，发送前重新检查权限。权限变更后需要重新订阅。</p></fieldset>
</section></template>
<style scoped>
.media-settings,fieldset { display:grid; gap:1rem; }fieldset { border:1px solid var(--border-color,#d8e4dc); border-radius:.75rem; padding:1rem; }legend { color:var(--text-primary,#335447); padding:0 .4rem; }.grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:1rem; }label { display:grid; gap:.45rem; font-size:.85rem; }.toggle { display:flex; align-items:center; gap:.5rem; }.toggle input { width:auto; }.hint { color:var(--text-secondary,#68756c);font-size:.82rem;line-height:1.6;margin:0; }textarea,input,select { width:100%;box-sizing:border-box;padding:.6rem .75rem;border:1px solid var(--border-color,#d8e4dc);border-radius:.55rem;background:var(--bg-surface,#fff);color:inherit;font:inherit; }.buttons { display:flex; flex-wrap:wrap; gap:.5rem; }button { padding:.5rem .8rem;border:1px solid #d8e4dc;border-radius:.5rem;background:#f1f7f3;color:#356a51;cursor:pointer; }button:disabled{opacity:.5}.qr { width:220px;max-width:100%; }@media(max-width:720px){.grid{grid-template-columns:1fr}}
</style>
